        "type": "object",
        "properties": {
          "po_id": {
            "type": "string",
            "description": "Purchase order id."
          },
          "amount_cents": {
            "type": "integer",
            "description": "Amount in cents."
          },
          "idempotency_key": {
            "type": "string",
            "nullable": true,
